#!/usr/bin/env python
"""Test the exact example from the issue description."""

from tornado.httputil import url_concat

# This was causing a crash before the fix
try:
    url = url_concat("https://localhost/path?r=1&t=2", None)
    print(f"Success! Result: {url}")
    print("✅ Issue has been fixed - no crash occurred")
except TypeError as e:
    print(f"❌ Issue still exists - crash occurred: {e}")

# Test with the URL from issue (note the space that was probably a typo)
try:
    url = url_concat("https: //localhost/path?r=1&t=2", None)
    print(f"With spaced URL: {url}")
except Exception as e:
    print(f"Spaced URL caused error (expected): {e}")
